    if (highScurvy > 0) factors.push(`⚠ ${highScurvy} crew with severe scurvy`);
    // Readiness formula
    const score = Math.round(0.30 * (skillCoverage * 100) + 0.25 * (crewSizeRatio * 100) + 0.20 * avgHealth + 0.15 * avgMorale + 0.10 * avgExp);
